BEGIN;
SET LOCAL ROLE s2a_management;
DO $$
DECLARE g bigint; u bigint; a bigint; b bigint; gem bigint; gem_oauth bigint; ag_catalog bigint; ts bigint; h text; decision jsonb; acquired jsonb; catalog jsonb;
BEGIN
 IF has_function_privilege('service_role','s2a_private.composite_resolve(bigint,text,text)','EXECUTE') THEN RAISE EXCEPTION 'private resolver exposed'; END IF;
 INSERT INTO public.users(email,password_hash,concurrency) VALUES('composite-'||gen_random_uuid()||'@example.invalid','!fixture',0) RETURNING id INTO u;
 INSERT INTO public.groups(name,platform) VALUES('Composite acceptance','composite') RETURNING id INTO g;
 INSERT INTO public.api_keys(user_id,group_id,key,name) VALUES(u,g,'synthetic-'||gen_random_uuid(),'Composite') RETURNING s2a_key_hash INTO h;
 INSERT INTO public.accounts(name,platform,type,credentials,concurrency,priority) VALUES('Composite OpenAI','openai','apikey','{"api_key":"synthetic","model_mapping":{"gpt-6":"gpt-6-sol","shared":"gpt-6","claude-owned":"gpt-6","public-openai":"gpt-6"}}',10,0) RETURNING id INTO a;
 INSERT INTO public.accounts(name,platform,type,credentials,concurrency,priority) VALUES('Composite Grok','grok','apikey','{"api_key":"synthetic","model_mapping":{"grok-*":"grok-4.6","shared":"grok-4.6"}}',10,0) RETURNING id INTO b;
 INSERT INTO public.account_groups(account_id,group_id) VALUES(a,g),(b,g);
 IF s2a_private.composite_resolve(g,'shared','responses')->>'error' IS DISTINCT FROM 'composite_model_ambiguous' THEN RAISE EXCEPTION 'ambiguous account ownership guessed'; END IF;
 IF s2a_private.composite_resolve(g,'claude-owned','responses')->>'platform' IS DISTINCT FROM 'openai' THEN RAISE EXCEPTION 'detector overrode account ownership'; END IF;
 IF s2a_private.composite_resolve(g,'unknown-model','responses')->>'error' IS DISTINCT FROM 'composite_model_unresolved' THEN RAISE EXCEPTION 'unknown model guessed'; END IF;
 INSERT INTO public.composite_model_routes(group_id,public_model,match_type,target_platform,upstream_model,endpoint,priority) VALUES
 (g,'alias','prefix','grok','','responses',0),
 (g,'alias-long','exact','openai','gpt-6','any',100),
 (g,'alias-long','exact','grok','grok-4.6','responses',200),
 (g,'alias-','prefix','openai','gpt-6','chat_completions',100);
 acquired:=public.s2a_personal_acquire(h,'__models__',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/v1/models"}');
 IF NOT acquired ? 'composite_catalog' OR acquired ? 'account' OR acquired ? 'lease_id' THEN RAISE EXCEPTION 'Composite catalog acquisition requires provider lease'; END IF;
 acquired:=public.s2a_personal_acquire(h,'__models__',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/backend-api/codex/models"}');
 IF NOT acquired ? 'composite_catalog' OR acquired ? 'account' OR acquired ? 'lease_id' THEN RAISE EXCEPTION 'Composite Codex catalog unavailable'; END IF;
 UPDATE public.api_keys SET ip_whitelist='["192.0.2.0/24"]'::jsonb WHERE s2a_key_hash=h;
 acquired:=public.s2a_personal_acquire(h,'__models__',gen_random_uuid(),p_client_ip=>'198.51.100.1',p_billing_context=>'{"inbound_endpoint":"/v1/models"}');
 IF acquired->>'error' IS DISTINCT FROM 'ip_forbidden' THEN RAISE EXCEPTION 'Composite catalog bypassed IP policy'; END IF;
 UPDATE public.api_keys SET ip_whitelist='[]'::jsonb WHERE s2a_key_hash=h;
 catalog:=s2a_private.composite_catalog_sources(g);
 IF jsonb_array_length(catalog->'capability_sources')<>2 THEN RAISE EXCEPTION 'Composite capability sources missing'; END IF;
 IF has_function_privilege('service_role','s2a_private.composite_capability_sources(bigint)','EXECUTE') THEN RAISE EXCEPTION 'private capability sources exposed'; END IF;
 UPDATE s2a_private.accounts SET overload_until=now()+interval '1 minute' WHERE id=b;
 IF jsonb_array_length(s2a_private.composite_catalog_sources(g)->'sources')<>1 OR jsonb_array_length(s2a_private.composite_catalog_sources(g)->'capability_sources')<>2 THEN RAISE EXCEPTION 'temporary cooldown narrowed capability intersection'; END IF;
 UPDATE s2a_private.accounts SET overload_until=NULL WHERE id=b;
 IF jsonb_array_length(catalog->'sources')<>2 OR jsonb_array_length(catalog->'routes')<>4 THEN RAISE EXCEPTION 'Composite catalog sources missing'; END IF;
 IF catalog::text LIKE '%synthetic%' OR catalog::text LIKE '%api_key%' OR catalog::text LIKE '%credential%' THEN RAISE EXCEPTION 'Composite catalog leaked provider credentials'; END IF;
 IF has_function_privilege('service_role','s2a_private.composite_catalog_sources(bigint)','EXECUTE') OR has_function_privilege('authenticated','s2a_private.composite_catalog_sources(bigint)','EXECUTE') THEN RAISE EXCEPTION 'private catalog exposed'; END IF;
 IF s2a_private.composite_catalog_sources(-1) IS DISTINCT FROM '{"sources":[],"routes":[],"capability_sources":[]}'::jsonb THEN RAISE EXCEPTION 'Composite catalog group isolation failed'; END IF;
 UPDATE s2a_private.accounts SET schedulable=false WHERE id=b;
 IF jsonb_array_length(s2a_private.composite_catalog_sources(g)->'sources')<>1 THEN RAISE EXCEPTION 'disabled account included in catalog'; END IF;
 UPDATE s2a_private.accounts SET schedulable=true WHERE id=b;
 decision:=s2a_private.composite_resolve(g,'alias-long','responses');
 IF decision->>'platform'<>'grok' OR decision->>'upstream_model'<>'grok-4.6' THEN RAISE EXCEPTION 'endpoint specificity failed'; END IF;
 decision:=s2a_private.composite_resolve(g,'alias-long','chat_completions');
 IF decision->>'platform'<>'openai' THEN RAISE EXCEPTION 'exact route did not beat endpoint prefix'; END IF;
 decision:=s2a_private.composite_resolve(g,'alias-other','responses');
 IF decision->>'upstream_model'<>'alias-other' THEN RAISE EXCEPTION 'blank prefix upstream collapsed model'; END IF;
 acquired:=public.s2a_personal_acquire(h,'alias-long',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/v1/chat/completions"}');
 IF acquired ? 'error' OR acquired->'account'->>'id' IS DISTINCT FROM a::text OR acquired->>'upstream_model' IS DISTINCT FROM 'gpt-6-sol' THEN RAISE EXCEPTION 'Composite account mapping chain failed: %',acquired->>'error'; END IF;
 UPDATE public.composite_model_routes SET upstream_model='grok-4.6',target_platform='grok' WHERE group_id=g AND public_model='alias-long' AND endpoint='any';
 decision:=public.s2a_personal_acquire(h,'alias-long',(SELECT request_id FROM s2a_private.personal_gateway_leases WHERE id=(acquired->>'lease_id')::uuid),p_billing_context=>'{"inbound_endpoint":"/v1/chat/completions"}');
 IF decision->>'lease_id' IS DISTINCT FROM acquired->>'lease_id' OR decision->>'upstream_model' IS DISTINCT FROM acquired->>'upstream_model' THEN RAISE EXCEPTION 'Composite route changed during replay'; END IF;
 acquired:=public.s2a_personal_acquire(h,'grok-4.6',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/v1/responses"}');
 IF acquired ? 'error' OR acquired->'account'->>'id' IS DISTINCT FROM b::text THEN RAISE EXCEPTION 'Composite detector did not select Grok'; END IF;
 acquired:=public.s2a_personal_acquire(h,'public-openai',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/v1/responses"}');
 IF acquired ? 'error' OR acquired->'account'->>'id' IS DISTINCT FROM a::text THEN RAISE EXCEPTION 'Composite exact account alias failed'; END IF;
 -- Scheduling and forwarding must normalize the same Gemini alias.
 INSERT INTO public.accounts(name,platform,type,credentials,concurrency) VALUES('Composite Gemini','gemini','apikey','{"api_key":"synthetic","model_mapping":{"gemini-3.1-pro-preview":"upstream-exact"}}',10) RETURNING id INTO gem;
 INSERT INTO public.account_groups(account_id,group_id) VALUES(gem,g);
 INSERT INTO public.accounts(name,platform,type,credentials,concurrency,priority) VALUES('Gemini catalog OAuth','gemini','oauth','{"access_token":"synthetic"}',10,-100) RETURNING id INTO gem_oauth;
 INSERT INTO public.account_groups(account_id,group_id) VALUES(gem_oauth,g);
 acquired:=public.s2a_personal_acquire(h,'__models__',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/v1beta/models"}');
 IF acquired ? 'error' OR acquired->'account'->>'id' IS DISTINCT FROM gem::text OR acquired ? 'composite_catalog' THEN RAISE EXCEPTION 'Native Composite Gemini catalog did not select a Gemini account'; END IF;
 IF acquired->'model_sources'->'mapping' IS DISTINCT FROM '{}'::jsonb THEN RAISE EXCEPTION 'Native Gemini catalog unexpectedly rewrites provider metadata'; END IF;
 acquired:=public.s2a_personal_acquire(h,'__models__',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/v1beta/models/gemini-3.1-pro-preview"}');
 IF acquired ? 'error' OR acquired->'account'->>'id' IS DISTINCT FROM gem::text THEN RAISE EXCEPTION 'Native Composite Gemini detail unavailable'; END IF;
 UPDATE public.accounts SET schedulable=false WHERE id=gem_oauth;
 INSERT INTO public.accounts(name,platform,type,credentials,extra,concurrency) VALUES('Antigravity catalog','antigravity','oauth','{"access_token":"synthetic-private","model_mapping":{"gemini-extra":"gemini-target"}}','{"mixed_scheduling":true}',10) RETURNING id INTO ag_catalog;
 INSERT INTO public.account_groups(account_id,group_id) VALUES(ag_catalog,g);
 catalog:=s2a_private.gemini_catalog_sources(g);
 IF catalog->'sources' IS DISTINCT FROM '[{"gemini-extra":"gemini-target"}]'::jsonb OR catalog->>'has_antigravity'<>'true' THEN RAISE EXCEPTION 'Mixed Gemini catalog sources unavailable'; END IF;
 IF catalog::text LIKE '%synthetic%' OR has_function_privilege('service_role','s2a_private.gemini_catalog_sources(bigint)','EXECUTE') THEN RAISE EXCEPTION 'Gemini catalog leaked private data or permissions'; END IF;
 IF s2a_private.gemini_catalog_sources(-1) IS DISTINCT FROM '{"has_antigravity":false,"sources":[]}'::jsonb THEN RAISE EXCEPTION 'Gemini catalog crossed group boundary'; END IF;
 UPDATE public.accounts SET schedulable=false WHERE id=gem;
 acquired:=public.s2a_personal_acquire(h,'__models__',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/v1beta/models"}');
 IF acquired->>'gemini_catalog_only' IS DISTINCT FROM 'true' OR acquired ? 'account' OR acquired ? 'lease_id' THEN RAISE EXCEPTION 'AG-only catalog requires a Gemini inference account'; END IF;
 UPDATE public.accounts SET schedulable=true WHERE id=gem;
 UPDATE public.accounts SET extra='{}' WHERE id=ag_catalog;
 IF jsonb_array_length(s2a_private.gemini_catalog_sources(g)->'sources')<>0 THEN RAISE EXCEPTION 'Mixed catalog ignored account opt-in'; END IF;
 UPDATE public.accounts SET schedulable=false WHERE id=ag_catalog;
 INSERT INTO public.composite_model_routes(group_id,public_model,target_platform,upstream_model,endpoint) VALUES(g,'gemini-public','gemini','gemini-3.1-pro-preview-customtools','responses');
 acquired:=public.s2a_personal_acquire(h,'gemini-public',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/v1/responses"}');
 IF acquired ? 'error' OR acquired->'account'->>'id' IS DISTINCT FROM gem::text OR acquired->>'upstream_model' IS DISTINCT FROM 'upstream-exact' THEN RAISE EXCEPTION 'Composite Gemini normalization lost mapped target'; END IF;
 UPDATE public.accounts SET credentials='{"api_key":"synthetic","model_mapping":{"gemini-3.1-pro-preview":"normalized","gemini-3.1-pro-preview-custom*":"raw-wildcard"}}' WHERE id=gem;
 acquired:=public.s2a_personal_acquire(h,'gemini-public',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/v1/responses"}');
 IF acquired->>'upstream_model' IS DISTINCT FROM 'raw-wildcard' THEN RAISE EXCEPTION 'Composite raw mapping must precede normalized fallback'; END IF;
 UPDATE public.accounts SET credentials='{"api_key":"synthetic","model_mapping":{"gemini-3.1-pro-preview":"antigravity-normalized"}}',platform='antigravity' WHERE id=gem;
 UPDATE public.composite_model_routes SET target_platform='antigravity' WHERE group_id=g AND public_model='gemini-public';
 acquired:=public.s2a_personal_acquire(h,'gemini-public',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/v1/responses"}');
 IF acquired->>'upstream_model' IS DISTINCT FROM 'antigravity-normalized' THEN RAISE EXCEPTION 'Composite Antigravity normalized mapping failed'; END IF;
 INSERT INTO public.accounts(name,platform,type,credentials,concurrency) VALUES('Composite TypeSafe','typesafe','apikey','{"api_key":"synthetic"}',10) RETURNING id INTO ts;
 INSERT INTO public.account_groups(account_id,group_id) VALUES(ts,g);
 INSERT INTO public.composite_model_routes(group_id,public_model,target_platform,upstream_model,endpoint) VALUES(g,'jev-latest','openai','gpt-6','responses');
 acquired:=public.s2a_personal_acquire(h,'jev-latest',gen_random_uuid(),p_billing_context=>'{"inbound_endpoint":"/v1/systemone"}');
 IF acquired ? 'error' OR acquired->'account'->>'id' IS DISTINCT FROM ts::text THEN RAISE EXCEPTION 'System One incorrectly used a Responses-specific Composite route'; END IF;
END $$;
ROLLBACK;
